  CONSTRAINT `reconciliation_log_ibfk_2` FOREIGN KEY (`subscriber_id`) REFERENCES `legal_entities` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
